files.tinycalc.py:
"""Flat calculator module. Everything lives here, the op table is maintained by hand,
and division is floating point. This is the thing you are migrating."""


class CalcError(ValueError):
    pass


def add(a, b):
    return a + b


def mul(a, b):
    return a * b


def divide(a, b):
    if b == 0:
        raise CalcError("cannot divide by zero")
    return a / b


OPS = {"pow": lambda a, b: a ** b}


def evaluate(op, a, b):
    if op not in OPS:
        raise CalcError("no such op")
    return OPS[op](a, b)

